ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (
    (ImageFileName=/\\vssadmin\.exe$/i AND CommandLine=/delete/i AND CommandLine=/shadows/i)
    OR (ImageFileName=/\\wmic\.exe$/i AND CommandLine=/shadowcopy/i AND CommandLine=/delete/i)
    OR (ImageFileName=/\\bcdedit\.exe$/i AND CommandLine=/(recoveryenabled\s+No|bootstatuspolicy\s+ignoreallfailures|safeboot)/i)
    OR (ImageFileName=/\\net\.exe$/i AND CommandLine=/stop/i AND CommandLine=/(veeam|mssql|sqlserver|backupexec|MSExchange|sophos)/i)
    OR (ImageFileName=/\\iisreset\.exe$/i AND CommandLine=/\/stop/i)
  )
| NOT UserName=/\$$/
| case {
    ImageFileName=/\\vssadmin\.exe$/i | Behavior := "vssadmin_delete_shadows";
    ImageFileName=/\\wmic\.exe$/i     | Behavior := "wmic_shadow_delete";
    ImageFileName=/\\bcdedit\.exe$/i  | Behavior := "bcdedit_inhibit_recovery";
    ImageFileName=/\\net\.exe$/i      | Behavior := "net_stop_backup_sql";
    ImageFileName=/\\iisreset\.exe$/i | Behavior := "iisreset_stop";
}
| bucket(span=10m, field=@timestamp, function=[collect_set(Behavior, as=Behaviors), count(as=evt_count)])
| groupBy([aid, ComputerName, UserName, _bucket], function=[collect_set(Behaviors, as=behaviors_in_window), count(as=evt_count)])
| length(behaviors_in_window) >= 2
| sort(_bucket, order=desc)
